const $=s=>document.querySelector(s),page=document.body.dataset.page;
const labels={economy:'經濟',environment:'環境',society:'社會'},phases={setup:'準備中',live:'交易進行中',paused:'已暫停',reflection:'反思階段'};
let token=sessionStorage.getItem(page+'Token')||'',cards=[],latest=null,pending=null,busy=false,refreshing=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function uid(){return globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
async function api(path,body){const response=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'content-type':'application/json',authorization:'Bearer '+token},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(12000)});const data=await response.json();if(!response.ok)throw Error(data.error||'連線失敗');return data}
function notice(msg,error=false){$('#notice').textContent=msg;$('#notice').className=error?'error':'success'}
function chart(history){const w=960,h=300,p=38,max=Math.max(6,...history.flatMap(x=>Object.keys(labels).map(k=>x[k]))),n=Math.max(1,history.length-1);let svg='';for(let i=0;i<=3;i++){const y=p+(h-2*p)*i/3;svg+=`<line x1="${p}" y1="${y}" x2="${w-p}" y2="${y}" stroke="#dde5dc"/><text x="4" y="${y+5}" fill="#607367" font-size="13">${Math.round(max*(1-i/3))}</text>`}Object.entries({economy:'#197cd2',environment:'#168458',society:'#c6920b'}).forEach(([k,c],j)=>{svg+=`<polyline fill="none" stroke="${c}" stroke-width="3" stroke-dasharray="${j===1?'8 3':j===2?'3 3':'none'}" points="${history.map((s,i)=>`${p+i/n*(w-2*p)},${h-p-s[k]/max*(h-2*p)}`).join(' ')}"/>`});svg+=`<text x="${p}" y="${h-5}" fill="#607367">開始</text><text x="${w-p}" y="${h-5}" text-anchor="end" fill="#607367">第 ${history.length-1} 筆有效交易</text>`;$('#chart').innerHTML=svg}
function world(s){$('#phase').textContent=phases[s.phase];for(const k of Object.keys(labels))$('#'+k).textContent=s.state[k];chart(s.history);$('#total').textContent=s.total;const events=$('#events');if(events){events.innerHTML=s.phase==='reflection'?'<h2>回顧世界的轉折</h2><p class="muted">依實際變化篩選：歸零、從零回升、單筆變化至少 2。這是討論線索，不是因果結論；未自動判斷卡片執行門檻。</p>'+((s.events||[]).map(e=>`<div class="event"><strong>第 ${e.step} 筆 · ${esc(e.group)} 組 · #${e.cardId} ${esc(e.name)}</strong><p>${e.reasons.map(r=>esc(r.replace(/economy|environment|society/g,k=>labels[k]))).join(' ／ ')}</p><span>${Object.keys(labels).map(k=>`${labels[k]} ${e.before[k]} → ${e.after[k]}`).join('　')}</span></div>`).join('')||'<p>目前沒有符合條件的事件。</p>'):''}}
async function refresh(){if(refreshing)return;refreshing=true;try{const s=await api(page==='admin'?'admin/state':'state');latest=s;$('#connection').textContent='● 已同步 · '+new Date().toLocaleTimeString('zh-TW');$('#connection').className='success';if(page==='dashboard'||page==='admin')world(s);if(page==='exchange'){$('#phase').textContent=phases[s.phase];const old=$('#group').value;$('#group').innerHTML=s.groups.map(g=>`<option value="${esc(g)}">${esc(g)} 組</option>`).join('');if(s.groups.includes(old))$('#group').value=old;$('#review').disabled=s.phase!=='live'||!cards.length||!!pending;const counts=await api('counts');$('#count').textContent=counts[$('#group').value]||0;}
if(page==='admin'){$('#cardCount').textContent=s.cardCount;$('#counts').innerHTML=s.groups.map(g=>`<span class="stat">${esc(g)} 組 <b>${s.counts[g]||0}</b> 次</span>`).join('');$('#rows').innerHTML=[...s.trades].reverse().map(t=>`<tr class="${t.voided?'void':''}"><td>${t.id}</td><td>${esc(t.group_name)}</td><td>#${t.card_id} ${esc(t.name)}</td><td>${t.economy} / ${t.environment} / ${t.society}</td><td>${new Date(t.created_at).toLocaleTimeString('zh-TW')}</td><td>${t.voided?esc(t.void_reason):`<button class="secondary" data-void="${t.id}">撤銷</button>`}</td></tr>`).join('');}
}catch(e){$('#connection').textContent='● 同步中斷 · '+e.message+'；目前顯示最後成功資料';$('#connection').className='error'}finally{refreshing=false}}
async function login(){token=$('#password').value;try{await api(page==='admin'?'admin/state':'cards');sessionStorage.setItem(page+'Token',token);$('#login').hidden=true;$('#workspace').hidden=false;if(page==='exchange'){cards=await api('cards');const p=sessionStorage.getItem('pendingTrade');if(p){pending=JSON.parse(p);$('#retry').hidden=false;notice('有一筆尚未確認結果的交易，請按「確認／重試上一筆」。')}}await refresh()}catch(e){notice(e.message,true)}}
if($('#loginButton'))$('#loginButton').onclick=login;
if(page==='dashboard')refresh();
if(page==='exchange'){
$('#group').onchange=()=>refresh();$('#review').onclick=()=>{const card=cards.find(c=>c.id===Number($('#cardId').value));if(!card)return notice('請輸入有效卡號 1–80',true);$('#confirmation').textContent=`${$('#group').value} 組｜#${card.id} ${card.name}`;$('#confirmDialog').showModal()};
$('#cancel').onclick=()=>$('#confirmDialog').close();$('#confirm').onclick=()=>{if(busy)return;pending={requestId:uid(),group:$('#group').value,cardId:Number($('#cardId').value)};sessionStorage.setItem('pendingTrade',JSON.stringify(pending));$('#confirmDialog').close();submit()};$('#retry').onclick=submit;
async function submit(){if(busy||!pending)return;busy=true;$('#retry').disabled=true;$('#review').disabled=true;try{const result=await api('trade',pending);notice(result.voided?'這筆交易已由引導師撤銷，未重新計入。':`${pending.group} 組交易成功！紀錄 #${result.id}`);pending=null;sessionStorage.removeItem('pendingTrade');$('#retry').hidden=true;$('#cardId').value='';await refresh()}catch(e){notice(e.message+'。請保留此頁並重試，不要重新登錄同一筆。',true);$('#retry').hidden=false}finally{busy=false;$('#retry').disabled=false}}
}
if(page==='admin'){
document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=async()=>{if(!confirm('確定切換為「'+phases[b.dataset.phase]+'」？'))return;try{await api('admin/phase',{phase:b.dataset.phase});notice('階段已更新');await refresh()}catch(e){notice(e.message,true)}});
$('#rows').onclick=async e=>{const id=Number(e.target.dataset.void);if(!id)return;const reason=prompt('撤銷原因（請先暫停交易）');if(!reason)return;try{await api('admin/void',{id,reason});notice('已撤銷並依交易順序重新計算');await refresh()}catch(e){notice(e.message,true)}};
$('#saveGroups').onclick=async()=>{try{await api('admin/groups',{groups:$('#groups').value.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean)});notice('組別已更新');await refresh()}catch(e){notice(e.message,true)}};
$('#import').onclick=async()=>{try{const f=$('#file').files[0];if(!f)throw Error('請選取轉換完成的 cards.json');const cards=JSON.parse(await f.text());await api('admin/import',{cards});notice('80 張卡片已匯入');await refresh()}catch(e){notice(e.message,true)}};
$('#export').onclick=()=>{if(!latest)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(latest,null,2)],{type:'application/json'}));a.download='SDGs-活動紀錄-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
}
setInterval(()=>{if(page==='dashboard'||($('#workspace')&&!$('#workspace').hidden))refresh()},2500);

