import {replay,validateCards} from './domain.mjs';
const json=(v,status=200)=>new Response(JSON.stringify(v),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
export async function handle(request,env){
 try{
 const url=new URL(request.url),path=url.pathname.replace('/api/',''),db=env.DB;
 if(!db)return json({error:'資料庫尚未設定'},503);
 const role=request.headers.get('x-role'),token=request.headers.get('authorization')?.replace(/^Bearer /,'');
 const admin=!!env.ADMIN_TOKEN&&token===env.ADMIN_TOKEN,operator=admin||(!!env.OPERATOR_TOKEN&&token===env.OPERATOR_TOKEN);
 if(path!=='state'&&!operator)return json({error:'請輸入正確的工作人員密碼'},401);
 if(path.startsWith('admin/')&&!admin)return json({error:'需要引導師密碼'},403);
 if(request.method==='POST'&&request.headers.get('origin')&&request.headers.get('origin')!==url.origin)return json({error:'來源不符'},403);
 const settings=await db.prepare('SELECT * FROM settings WHERE id=1').first();
 if(request.method==='GET'){
 if(path==='state'||path==='admin/state'){
 const rows=(await db.prepare('SELECT * FROM trades ORDER BY id').all()).results,r=replay(rows);
 const result={phase:settings.phase,groups:JSON.parse(settings.groups_json),state:r.state,history:r.history,total:r.total};
 if(path==='admin/state'){result.trades=rows;result.counts=r.counts;result.cardCount=(await db.prepare('SELECT count(*) AS n FROM cards').first()).n;}
 if(settings.phase==='reflection')result.events=r.events;
 return json(result);
 }
 if(path==='cards'){return json((await db.prepare('SELECT id,name FROM cards ORDER BY id').all()).results);}
 if(path==='counts'){return json(replay((await db.prepare('SELECT * FROM trades ORDER BY id').all()).results).counts);}
 }
 if(request.method!=='POST')return json({error:'找不到此功能'},404);
 const body=await request.json();
 if(path==='trade'){
 if(!/^[a-zA-Z0-9-]{16,80}$/.test(body.requestId||''))return json({error:'交易識別碼不正確'},400);
 const old=await db.prepare('SELECT * FROM trades WHERE request_id=?').bind(body.requestId).first();
 if(old){if(old.group_name!==body.group||old.card_id!==Number(body.cardId))return json({error:'交易識別碼已使用'},409);return json({ok:true,id:old.id,duplicate:true,voided:!!old.voided});}
 if(!JSON.parse(settings.groups_json).includes(body.group))return json({error:'組別不存在'},400);
 const result=await db.prepare(`INSERT OR IGNORE INTO trades(request_id,group_name,card_id,name,economy,environment,society) SELECT ?,?,id,name,economy,environment,society FROM cards WHERE id=? AND (SELECT phase FROM settings WHERE id=1)='live' AND EXISTS (SELECT 1 FROM json_each((SELECT groups_json FROM settings WHERE id=1)) WHERE value=?)`).bind(body.requestId,body.group,Number(body.cardId),body.group).run();
 const saved=await db.prepare('SELECT id FROM trades WHERE request_id=?').bind(body.requestId).first();
 if(!saved)return json({error:'尚未開放交易、已暫停，或卡號無效'},409);
 return json({ok:true,id:saved.id});
 }
 if(path==='admin/phase'){
 if(!['setup','live','paused','reflection'].includes(body.phase))return json({error:'階段無效'},400);
 if(body.phase==='live'&&(await db.prepare('SELECT count(*) AS n FROM cards').first()).n!==80)return json({error:'請先匯入完整 80 張正式卡片'},409);
 await db.prepare('UPDATE settings SET phase=? WHERE id=1').bind(body.phase).run();return json({ok:true});
 }
 if(path==='admin/void'){
 if(!Number.isInteger(body.id)||typeof body.reason!=='string'||!body.reason.trim()||body.reason.length>200)return json({error:'請提供交易編號與撤銷原因（200字內）'},400);
 const r=await db.prepare("UPDATE trades SET voided=1,void_reason=?,voided_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=? AND voided=0 AND (SELECT phase FROM settings WHERE id=1)!='live'").bind(body.reason,body.id).run();
 return r.meta.changes?json({ok:true}):json({error:'請先暫停交易；紀錄可能已撤銷或不存在'},409);
 }
 if(path==='admin/import'){
 validateCards(body.cards);
 // Every statement is guarded; D1 batch is an atomic transaction.
 const guard="NOT EXISTS (SELECT 1 FROM trades) AND (SELECT phase FROM settings WHERE id=1)='setup'";
 const results=await db.batch([db.prepare(`DELETE FROM cards WHERE ${guard}`),...body.cards.map(c=>db.prepare(`INSERT OR REPLACE INTO cards SELECT ?,?,?,?,? WHERE ${guard}`).bind(c.id,c.name,c.economy,c.environment,c.society))]);
 if(!results[1].meta.changes)return json({error:'僅可於準備階段、尚無交易時匯入'},409);return json({ok:true,count:80});
 }
 if(path==='admin/groups'){
 const g=body.groups;if(!Array.isArray(g)||g.length<1||g.length>60||new Set(g).size!==g.length||g.some(x=>typeof x!=='string'||!x.trim()||x.length>20))return json({error:'組別須為1–60組，名稱不可重複或空白'},400);
 const r=await db.prepare("UPDATE settings SET groups_json=? WHERE id=1 AND phase='setup' AND NOT EXISTS (SELECT 1 FROM trades)").bind(JSON.stringify(g)).run();return r.meta.changes?json({ok:true}):json({error:'已有交易或非準備階段，不能修改組別'},409);
 }
 return json({error:'找不到此功能'},404);
 }catch(e){return json({error:e.message?.includes('80')||e.message?.includes('卡號')||e.message?.includes('增減')||e.message?.includes('名稱')?e.message:'處理失敗，請檢查輸入或稍後重試'},400);}
}

