export const axes=['economy','environment','society'];
export function replay(trades){
 let state={economy:3,environment:3,society:3},history=[{step:0,...state}],events=[],counts={};
 for(const t of trades){if(t.voided)continue; const before={...state};for(const k of axes)state[k]=Math.max(0,state[k]+t[k]);
 counts[t.group_name]=(counts[t.group_name]||0)+1; const step=history.length;history.push({step,...state});
 const reasons=[]; for(const k of axes){if(before[k]>0&&state[k]===0)reasons.push(`${k}:歸零`);if(before[k]===0&&state[k]>0)reasons.push(`${k}:從零回升`);if(Math.abs(state[k]-before[k])>=2)reasons.push(`${k}:單筆變化至少2`);}
 if(reasons.length)events.push({step,tradeId:t.id,group:t.group_name,cardId:t.card_id,name:t.name,before,after:{...state},reasons});
 }return {state,history,counts,total:history.length-1,events};
}
export function validateCards(cards){
 if(!Array.isArray(cards)||cards.length!==80)throw Error('正式資料必須恰好有 80 張卡');
 const seen=new Set();for(const c of cards){if(!Number.isInteger(c.id)||c.id<1||c.id>80||seen.has(c.id))throw Error('卡號必須為 1–80，不可重複');seen.add(c.id);if(typeof c.name!=='string'||!c.name.trim()||c.name.length>200)throw Error('專案名稱不可空白且須在200字內');for(const k of axes)if(!Number.isInteger(c[k])||Math.abs(c[k])>100)throw Error('三項增減值須為 -100 到 100 的整數');}return cards;
}
